function checkHPP($param) {
    $paramValues = [];
    foreach ($_GET as $key => $value) {
        if ($key === $param) {
            $paramValues[] = $value;
        }
    }
    if (count($paramValues) > 1) {
        return true;
    }
    return false;
}

if (checkHPP('param1')) {
    echo "HTTP Parameter Pollution detected.";
} else {
    echo "No HTTP Parameter Pollution detected.";
}
```

